            self.i += 1
            self.skip_ws()
            start=self.i
            while self.i < len(self.s) and self.s[self.i] not in ',();':
                self.i += 1
            tok=self.s[start:self.i].strip()
            return float(tok)
        return None
    def parse_subtree(self):
        self.skip_ws()
        if self.i < len(self.s) and self.s[self.i] == '(':
            self.i += 1
            idx=self.new_node()
            while True:
                child=self.parse_subtree()
                self.nodes[idx]['children'].append(child)
                self.skip_ws()
                if self.i < len(self.s) and self.s[self.i] == ',':
                    self.i += 1
                    continue
                if self.i < len(self.s) and self.s[self.i] == ')':
                    self.i += 1
                    break
                raise ValueError(f'Expected comma or close paren at {self.i}: {self.s[self.i:self.i+20]"'!r}'"')
            # Optional internal label/support before optional length.
            if self.i < len(self.s) and self.s[self.i] not in ':,();':
                self.nodes[idx]['name']=self.parse_label()
            self.nodes[idx]['length']=self.parse_length()
            return idx
