    vals=[]; leaves_count=collections.Counter(); failures=[]
    with zipfile.ZipFile(zpath) as z:
        names=sorted(n for n in z.namelist() if n.endswith('.treefile'))
        for name in names:
            try:
                s=z.read(name).decode().strip()
                val, leaves=mean_patristic(s)
                vals.append((name,val,len(leaves),tuple(sorted(leaves))))
                leaves_count[len(leaves)] += 1
            except Exception as e:
                failures.append((name,str(e)))
    med=statistics.median(v for _,v,_,_ in vals)
    return vals, med, leaves_count, failures

for group,zp in [('animals','inputs/scogs_animals.zip'),('fungi','inputs/scogs_fungi.zip')]:
    vals, med, lc, failures=summarize(zp)
    print(group, 'trees', len(vals), 'failures', len(failures), 'leaf_counts', dict(sorted(lc.items())), 'median_mean_patristic', repr(med))
    print('  min/median/max means', min(v for _,v,_,_ in vals), med, max(v for _,v,_,_ in vals))
    print('  first sorted values around median:')
    sorted_vals=sorted(vals,key=lambda x:x[1])
    mid=len(sorted_vals)//2
    for rec in sorted_vals[max(0,mid-2):mid+3]:
        print(' ', rec[0], rec[1], rec[2])
    if failures[:3]: print(' failures sample', failures[:3])

